def proposals():
    keys = ["job_id_global", "proposed_decision", "family_status", "proposed_family", "boundary_group", "main_duty",
            "evidence_field", "evidence_quote", "reason", "certainty"]
    records = []
    for line in REVIEW.splitlines():
        if line:
            values = line.split("|")
            if len(values) != len(keys):
                raise ValueError(f"Annotation column count: {values[0]}")
            item = dict(zip(keys, values, strict=True))
            item["scope_status"] = "out_of_scope_proposed" if item["proposed_decision"] == "exclude_proposed" else "in_scope_proposed" if item["proposed_decision"] == "retain_proposed" else "scope_unresolved"
            records.append(item)
    return records
